func TestChannelProjectedActivityResultJournalsAndReplaysAcrossSelectedStores(t *testing.T) {
	for _, tc := range activityBoringStoreCases() {
		t.Run(tc.name, func(t *testing.T) {
			ctx := testAuthorActivityContext(t, context.Background())
			runID := uuid.NewString()
			var calls atomic.Int32
			server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
				calls.Add(1)
				w.Header().Set("Content-Type", "application/json")
				_, _ = io.WriteString(w, `{"ok":true,"result":{"message_id":42}}`)
			}))
			defer server.Close()
			db, store, sqlite := newActivityJournalStoreForCase(t, ctx, tc.kind)
			seedActivityRun(t, db, sqlite, runID)
			source := semanticview.Wrap(&runtimecontracts.WorkflowContractBundle{Tools: map[string]runtimecontracts.ToolSchemaEntry{"channel.ops.deliver": testCompiledChannelActivityTool(server.URL)}})
			bus := &recordingPipelineBus{}
			pc := newDurablePipelineCoordinatorForTest(bus, db, PipelineCoordinatorOptions{Module: staticSemanticWorkflowModule{source: source}, Persistence: workflowPersistenceForTest(store), PipelineObligations: unavailablePipelineTestObligationOwner{}})
			intent := testNonIdempotentActivityIntent(runID, uuid.NewString(), uuid.NewString())
			intent.Tool = "channel.ops.deliver"
			intent.ActivityID = "channel_deliver"
			intent.SuccessEvent = "channel.deliver.succeeded"
			intent.FailureEvent = "channel.deliver.failed"
			request, err := activityRequestEmitIntent(intent)
			if err != nil {
				t.Fatalf("activityRequestEmitIntent: %v", err)
			}
			if handled, _, err := pc.handleEventResult(ctx, request.Event); err != nil || !handled {
				t.Fatalf("first handle = %v, err=%v", handled, err)
			}
			pc = newDurablePipelineCoordinatorForTest(bus, db, PipelineCoordinatorOptions{Module: staticSemanticWorkflowModule{source: source}, Persistence: workflowPersistenceForTest(store), PipelineObligations: unavailablePipelineTestObligationOwner{}})
			if handled, _, err := pc.handleEventResult(ctx, request.Event); err != nil || !handled {
				t.Fatalf("replay handle = %v, err=%v", handled, err)
			}
			if calls.Load() != 1 {
				t.Fatalf("provider calls = %d, want one across replay", calls.Load())
			}
			if len(bus.publishes) != 2 || bus.publishes[0].ID() != bus.publishes[1].ID() {
				t.Fatalf("published replay events = %#v, want same journaled result twice", bus.publishes)
			}
			var payload map[string]any
			if err := json.Unmarshal(bus.publishes[1].Payload(), &payload); err != nil {
				t.Fatalf("decode replay payload: %v", err)
			}
			want := map[string]any{"delivery_reference": map[string]any{"id": float64(42)}}
			if !reflect.DeepEqual(payload["result"], want) {
				t.Fatalf("journaled channel result = %#v, want %#v", payload["result"], want)
			}
			projection, ok := testCompiledChannelActivityTool(server.URL).CompiledResultExecution()
			if !ok {
				t.Fatal("missing admitted channel result projection")
			}
			rawSchema, err := json.Marshal(projection.OutputSchema())
			if err != nil {
				t.Fatal(err)
			}
			var resultSchema map[string]any
			if err := json.Unmarshal(rawSchema, &resultSchema); err != nil {
				t.Fatal(err)
			}
			payloadSchema, err := runtimecontracts.ResolveJSONSchemaStructuralType(map[string]any{"type": "object", "required": []string{"result"}, "properties": map[string]any{"result": resultSchema}}, "channel-result-proof")
			if err != nil {
				t.Fatal(err)
			}
			for _, published := range bus.publishes {
				var executionPayload map[string]any
				if err := canonicaljson.DecodePreservingNumberLexemes(published.Payload(), &executionPayload); err != nil {
					t.Fatal(err)
				}
				for _, proof := range []struct {
					expression string
					want       any
				}{{"payload.result.delivery_reference.id + 1", int64(43)}, {"double(payload.result.delivery_reference.id) + 1.0", float64(43)}} {
					got, err := workflowexpr.EvalValueExpressionWithOptions(proof.expression, workflowexpr.ValueContext{Payload: executionPayload}, workflowexpr.ValueExpressionOptions{PayloadType: &payloadSchema})
					if err != nil || got != proof.want {
						t.Fatalf("journal numeric expression %s: got %#v want %#v err=%v", proof.expression, got, proof.want, err)
					}
				}
			}
		})
	}
}

