			Evidence: *transition, TransitionID: transition.ID(), From: transition.From(), To: transition.To(),
			TriggerEventID: inbound.ID(), FiredAt: inbound.CreatedAt(), GuardsEvaluated: transition.GuardsEvaluated(),
		})
	}
