				for i := 0; i < 2; i++ {
					if err := pc.ReconcileInitialEntryTimersForAttempt(ctx, identity, attempt, construction.Plan.Readiness); err != nil {
						t.Fatalf("production declaration reconciliation: %v", err)
					}
