	if got := len(newDeliveries); got != 2 {
		t.Fatalf("new deliveries = %d, want 2", got)
	}
	for _, item := range newDeliveries {
		delivery := asMap(t, item)
		if strings.TrimSpace(fmt.Sprint(delivery["source_delivery_id"])) == "" {
