							return fmt.Errorf("unexpected repeated %s handler attempt", second)
						}
					case <-ctx.Done():
						return fmt.Errorf("wait for %s fixture handshake: %w", first, ctx.Err())
					}
				})
				for _, group := range transcript.groups {
					for _, step := range group.steps {
						var preserved map[flowidentity.RunScopedFlowInstance]runtimepipeline.WorkflowInstance
						if step.ReceiptFailureClass == "platform.conflicting_duplicate" {
							preserved = captureCatalogConstruction(t, h.ctx, h.workflow, workerPath)
						}
						if step.Event == "flow.finished" {
							parent, found, err := h.workflow.Load(h.ctx, catalogRootWorkflowRoute())
							if err != nil || !found || parent.CurrentState != "spawned" {
								t.Fatalf("duplicate-creation parent must remain spawned until explicit finish: found=%v err=%v state=%q", found, err, parent.CurrentState)
							}
						}
						if err := h.publishRuntimeEventResultForStep(step, catalogRuntimePublishTimeout, true); err != nil {
							var reader operatorread.ObservabilityReader = h.pg
							if h.sqlite != nil {
								reader = h.sqlite
							}
							logs, readErr := reader.ListOperatorRuntimeLogs(h.ctx, operatorread.OperatorRuntimeLogListOptions{RunID: catalogRuntimeRunID, Limit: 30})
							t.Logf("creation event=%s diagnostics error=%v", step.Event, readErr)
							for _, log := range logs.Logs {
								t.Logf("creation diagnostic: %+v", log)
							}
							observed, observedErr := catalogRunScopedOperatorEvents(h, catalogRuntimeRunID)
							t.Logf("creation event readback error=%v", observedErr)
							for id, event := range observed {
								t.Logf("creation event id=%s type=%s deliveries=%+v no_delivery=%+v dead_letters=%+v", id, event.EventName, event.Deliveries, event.NoDelivery, event.DeadLetters)
							}
							t.Fatal(err)
						}
						assertCatalogConstructionUnchanged(t, h.ctx, h.workflow, preserved)
					}
					h.waitForCatalogStoreQuiescence(catalogRuntimePublishTimeout)
				}
				h.waitForExpectedEmittedEvents(transcript.expected, catalogRuntimePublishTimeout)
				h.waitForCatalogStoreQuiescence(catalogRuntimePublishTimeout)
				for _, mutate := range mutations {
					mutate(&transcript.expected)
				}
				assertCatalogRuntimeOutcome(t, h, transcript.expected)
				assertCatalogReplayFixtureOutcome(t, fixture, h, transcript)
				select {
				case state := <-observedState:
					if state != waitingState {
						t.Fatalf("first handler committed state=%q, want %q", state, waitingState)
					}
				default:
					t.Fatal("second handler never observed the first handler's committed state")
				}
				transcript.requireUnchanged(t)
			})
		}
	}
}

