	assertNodeDeliveryStatus(t, pg, evt.ID(), targetRoute.Recipient.ID(), "delivered")
	select {
	case got := <-live:
		t.Fatalf("consumed mixed node route event leaked to workflow-runtime carrier: %#v", got)
	default:
	}
}

