		t.Fatalf("load child workflow instance: found=%t err=%v", childFound, err)
	}
	grandchildInstance, grandchildFound, err := workflowStore.Load(ctx, testRunScopedFlowRoute(runtimeflowidentity.RouteForInstancePath("child/grandchild")))
	if err != nil || !grandchildFound {
		t.Fatalf("load grandchild workflow instance: found=%t err=%v", grandchildFound, err)
	}
	childState := strings.TrimSpace(childInstance.CurrentState)
	grandchildState := strings.TrimSpace(grandchildInstance.CurrentState)
	instances := []runtimepipeline.WorkflowInstance{childInstance, grandchildInstance}
	var emitted []string
	rows, err := db.QueryContext(context.Background(), `SELECT event_name FROM events ORDER BY created_at ASC, event_id ASC`)
	if err != nil {
		t.Fatalf("query events: %v", err)
	}
	defer rows.Close()
	for rows.Next() {
		var name string
		if err := rows.Scan(&name); err != nil {
			t.Fatalf("scan event: %v", err)
		}
		emitted = append(emitted, strings.TrimSpace(name))
	}
	if err := rows.Err(); err != nil {
		t.Fatalf("iterate events: %v", err)
	}
	if childState != "completed" {
		t.Fatalf("child current_state = %q, want completed; events=%v instances=%#v", childState, emitted, instances)
	}
	if grandchildState != "finished" {
		t.Fatalf("grandchild current_state = %q, want finished; events=%v instances=%#v nodes=%#v", grandchildState, emitted, instances, module.WorkflowNodes())
	}
	if contains(emitted, "child/step.result") {
		t.Fatalf("events = %v, do not want child/step.result", emitted)
	}
	if contains(emitted, "pipeline.complete") {
		t.Fatalf("events = %v, do not want retired dead output pipeline.complete", emitted)
	}
}

