				t.Fatalf("setup calls after acknowledged fault = %d, want 1", setup.calls)
			}

			replayed, err := executeTestSetupEntities(ctx, req, opts, now)
			if err != nil {
				t.Fatalf("idempotent replay error = %v", err)
