				t.Fatalf("idempotent replay result = %#v, want %#v", replayed, committed)
			}
			if setup.calls != 1 {
				t.Fatalf("setup calls after replay = %d, want no duplicate domain write", setup.calls)
			}
			assertScenarioSetupAckRows(t, db, runID, entityID)
		})
	}
}

