							t.Fatal(err)
						}
					}
					arrival = eventtest.ExistingRunRootIngressWithRoutingSource(uuid.NewString(), events.EventType(identity.InstancePath+"/item.completed"), "operator", "", []byte(`{"order_id":"order-1","member_id":"a","result":"accepted"}`), 0, runID, events.EnvelopeForEntityID(events.EventEnvelope{}, identity.EntityID), producer, now)
					if err := bus.PublishAcknowledged(ctx, arrival); err != nil {
						t.Fatal(err)
					}
					a2KnownTargetWaitForSettlement(t, ctx, bus, probe, arrival, node.Key(), "completed", "delivered", logger)
