					if err != nil || !found || len(publication.DeliveryRoutes) != 1 || len(publication.DeliveryRoutes[0].Context.Joins) != 1 || !publication.DeliveryRoutes[0].Context.Joins[0].Ref.Equal(plannedArm.JoinRef()) {
