					}
				}
				if arm := exactJoinPersistedArmForOwner(t, final, owner); !arm.OutcomeFired || arm.OutcomePending || !arm.JoinRef().Equal(plannedArm.JoinRef()) || final.Fields["final_count"] != int64(scenario.count) {
