						if status == "dead_letter" && (snapshot.Failure == nil || snapshot.Failure.Class != failures.ClassStaleArrival || snapshot.Failure.Retryable) {
							t.Fatalf("already-bound late work lacks a counted typed refusal: %#v", snapshot)
						}
					}
