			if err != nil || len(outcomesBefore) != 1 || outcomesBefore[0].Outcome != "delivered" || outcomesBefore[0].Failure != nil || outcomesBefore[0].ClaimVersion != deliveryBefore.ClaimVersion || outcomesBefore[0].SettledAt.IsZero() || !reflect.DeepEqual(outcomesBefore[0].SideEffects, []string{"handler_completed"}) || !deliveryBefore.FinalSelection.Present() {
