				if receipt.Disposition != events.JoinAdmissionEarly || !receipt.Ref.StageEntry().Empty() || receipt.Ref.HandlerEvent() != "item.completed" || receipt.Ref.Stage() != "awaiting" || !receipt.Ref.Node().Equal(collector) {
