						wantExpected, wantCompleted = 3, index+1
					}
					if arm.Status != joinruntime.StatusClosed || arm.CloseReason != joinruntime.CloseReasonUntil || !arm.OutcomePending || arm.OutcomeFired || arm.Expected() != wantExpected || arm.Completed() != wantCompleted {
