					}
					if arm.JoinRef().HandlerEvent() == "alternate.completed" {
						missing, values = []string{}, []any{map[string]any{"value": "A-E2-alternate-z"}}
						if index == 1 {
							values = []any{map[string]any{"value": "B-E1-alternate-x"}, map[string]any{"value": "B-E1-alternate-z"}}
						}
					}
