					assertExactJoinDeliveryCount(t, selected, ctx, event.ID(), node.Key(), 1)
					assertPersistedHandlerRuleSelection(t, selected, ctx, event.ID(), tc.context, tc.disposition, tc.semanticPath, tc.label)
