				}
				wantStatus := "delivered"
				if conflict {
					wantStatus = "dead_letter"
				}
				if status != wantStatus || outcomes != 1 {
					t.Fatalf("appearance settlement: %s/%d want %s/1", status, outcomes, wantStatus)
				}
			})
