			for i := 0; i < 200; i++ {
				eventID := seedGateRecoveryRouteObligation(t, selected, runID, oldAt.Add(time.Duration(i)*time.Millisecond))
				deferred[eventID] = struct{}{}
				setGateRecoveryRouteAttempt(t, selected, eventID, 1)
