					prepared, found, readErr := reader.LoadPreparedPublishEvent(ctx, event.ID())
					missingReceipt := readErr != nil || !found || len(prepared.DeliveryRoutes) != 1 || len(prepared.DeliveryRoutes[0].Context.Joins) != 1
