					assertExactJoinDeliveryStatus(t, selected, ctx, event.ID(), joinNode.Key(), "delivered")
					waitCtx, cancel := context.WithTimeout(ctx, 5*time.Second)
					if err := eventBus.WaitForQuiescence(waitCtx); err != nil {
						cancel()
