				if err := rt.DB.QueryRow(`SELECT COUNT(*) FROM entity_mutations WHERE run_id=$1 AND entity_id=$2`, setup.RunID, period.Entity.EntityID).Scan(&count); err != nil {
					t.Fatal(err)
