				}
				childRows := readForkReceiverRows(t, rt, fork.ForkRunID)
				if len(childRows) != 3 || !reflect.DeepEqual(childRows["consumer"], sourceRows["consumer"]) || !reflect.DeepEqual(childRows["producer"], producer) {
