			if err := rt.DB.QueryRow(`SELECT COUNT(*) FROM entity_state WHERE run_id=$1`, runID).Scan(&count); err != nil {
				t.Fatal(err)
			}
			if count != 7 {
				t.Fatalf("root plus two template/second-template/final chains: entities=%d", count)
			}
			for _, s := range siblings {
