					requireServedEventPublishEntityState(t, rt.ReceiverStateReader, rt.Backend, seed.RunID, "", "active")
					params = map[string]any{"event_name": "work.requested", "run_id": seed.RunID, "source_event_id": seed.EventID, "payload": map[string]any{"seed": true}, "idempotency_key": "ordinary-cross-flow"}
				}
				started := requireServedEventPublishRPCResult(t, rt.Endpoint, params)
				waitServedRunDeliveryQuiescence(t, rt.ReadRunDeliveries, started.RunID)
				var status string
				if err := rt.DB.QueryRow(`SELECT status FROM event_deliveries WHERE event_id = $1`, started.EventID).Scan(&status); err != nil {
					t.Fatal(err)
				}
				if status != "delivered" {
					t.Fatalf("ordinary producer delivery should execute and settle: %s", status)
				}
				var count int
				if err := rt.ReceiverStateReader.InspectSnapshot(context.Background(), func(ctx context.Context) error {
					var err error
					count, err = storetest.CountRunStateEntityStorage(ctx, rt.ReceiverStateReader, started.RunID, "done")
					return err
				}); err != nil {
					t.Fatal(err)
				}
				if count != 2 {
					t.Fatalf("ordinary producer and sink should both complete; got %d entities", count)
				}
				var parentID, childID string
				if err := rt.DB.QueryRow(`SELECT entity_id FROM entity_state WHERE run_id=$1 AND flow_instance='sink'`, started.RunID).Scan(&childID); err != nil {
					t.Fatal(err)
				}
				if err := rt.DB.QueryRow(`SELECT entity_id FROM entity_state WHERE run_id=$1 AND flow_instance<>'sink'`, started.RunID).Scan(&parentID); err != nil {
					t.Fatal(err)
				}
				if childID != flowidentity.EntityID("sink") || childID == parentID {
					t.Fatalf("child borrowed source state: parent=%s child=%s", parentID, childID)
				}
				duplicate := requireServedEventPublishRPCResult(t, rt.Endpoint, params)
				if duplicate.EventID != started.EventID {
					t.Fatal("exact duplicate created a second source event")
				}
				requireReceiverPublicReadback(t, rt.Endpoint, rt.ReceiverStateReader, started.RunID)
			})
		}
	}
}

Before:
func waitServedRunDeliveryQuiescence(t *testing.T, db *sql.DB, backend, runID string) {
	t.Helper()
	deadline := time.Now().Add(servedProofPollDeadline)
	stable := 0
	for time.Now().Before(deadline) {
		var active int
		query := `
			SELECT COUNT(*)
			FROM event_deliveries
			WHERE run_id = ?
			  AND status IN ('pending', 'in_progress')
		`
		if backend == "postgres" {
			query = `
				SELECT COUNT(*)
				FROM event_deliveries
				WHERE run_id = $1::uuid
				  AND status IN ('pending', 'in_progress')
			`
		}
		if err := db.QueryRowContext(context.Background(), query, runID).Scan(&active); err != nil {
			t.Fatalf("count active served run deliveries: %v", err)
		}
		if active == 0 {
			stable++
			if stable == 4 {
				return
			}
		} else {
			stable = 0
		}
		time.Sleep(25 * time.Millisecond)
	}
	t.Fatalf("served run %s deliveries did not remain quiescent\n%s", runID, servedEventPublishDebugSummary(t, db, backend, runID))
}

After:
func waitServedRunDeliveryQuiescence(t *testing.T, reader servedRunDeliveryReader, runID string) {
	t.Helper()
	if reader == nil {
		t.Fatal("served delivery quiescence requires its native run summary reader")
	}
	deadline := time.Now().Add(servedProofPollDeadline)
	stable := 0
	var last runtimedelivery.RunSummary
	for time.Now().Before(deadline) {
		summary, err := reader(context.Background(), runID)
		if err != nil {
			t.Fatalf("count active served run deliveries: %v", err)
		}
		if summary.RunID != runID {
			t.Fatalf("delivery summary run=%q,want exact %q", summary.RunID, runID)
		}
		if err := summary.Validate(); err != nil {
			t.Fatalf("invalid served run delivery summary: %v", err)
		}
		last = summary
		active := summary.Pending + summary.InProgress
		if active == 0 {
			stable++
			if stable == 4 {
				return
			}
		} else {
			stable = 0
		}
		time.Sleep(25 * time.Millisecond)
	}
	t.Fatalf("served run %s deliveries did not remain quiescent: %+v", runID, last)
}

