			terminal    bool
		}{
			{".", "ready", false}, {".", "Ready", true}, {".", "shared", false}, {"child", "shared", true},
		} {
			t.Run(backend+"/terminal_guard/"+tc.flow+"/"+tc.stage, func(t *testing.T) {
