			}
			owner := f.pc.deliveryStore.(*pipelineTestDeliveryOwner)
			if err := owner.commitInitial(f.ctx, evt, route); err != nil {
				t.Fatal(err)
			}
			id, err := runtimedelivery.DeliveryID(evt.ID(), route)
			if err != nil {
				t.Fatal(err)
			}
			before, _ := f.load()
