		t.Fatalf("join handler did not resolve: %#v", resolved)
	}
	if _, err := store.deliveryStore.ProveHandoff(ctx, evt.ID(), route); err != nil {
		t.Fatalf("seeded join delivery was not authorized: %v", err)
	}
