					}
					before := h.instance()
					h.restart()
					if err := h.replay(event); err != nil {
						t.Fatalf("duplicate completed outcome after replacement: %v", err)
					}
					if !exactJoinSemanticStateEqual(before, h.instance()) {
						t.Fatal("old outcome borrowed or mutated replacement generation")
					}
