				if found && declaration.ID == compiled.Edge().TimerID && activation.EntityID == effect.EntityID().String() {
					if occurrence != "" {
						return effect, fmt.Errorf("timer component requires one exact activation")
					}
					occurrence = activation.Ref.ActivationID
				}
			}
