				t.Fatalf("UpsertAgent(%s): %v", identity, err)
			}
			firstProjection, err := events.NewDeliveryPayloadProjection(map[string]string{"route_marker": "first"})
			if err != nil {
				t.Fatal(err)
			}
			secondProjection, err := events.NewDeliveryPayloadProjection(map[string]string{"route_marker": "second"})
			if err != nil {
				t.Fatal(err)
			}
			routes := []events.DeliveryRoute{{Recipient: events.MustAgentDeliveryRecipient(agentID), AgentIdentity: identity, Target: events.MustExistingEntityTarget(events.RouteIdentity{FlowID: "target-flow", FlowInstance: identity.FlowInstance(), EntityID: uuid.NewString()}), Context: events.DeliveryContext{Reply: &events.ReplyContextRef{ID: "reply-first"}}, PayloadProjection: firstProjection}, {Recipient: events.MustAgentDeliveryRecipient(agentID), AgentIdentity: identity, Target: events.MustExistingEntityTarget(events.RouteIdentity{FlowID: "target-flow", FlowInstance: identity.FlowInstance(), EntityID: uuid.NewString()}), Context: events.DeliveryContext{Reply: &events.ReplyContextRef{ID: "reply-second"}}, PayloadProjection: secondProjection}}
