func TestFanInBarrierCanonicalRuntimeCompletesAfterRestartOnBothBackends(t *testing.T) {
	canonicalrouting.Prove(t, canonicalrouting.FanInBarrier)
	repoRoot := canonicalrouting.RepoRoot(t)
	bundle, err := runtimecontracts.LoadWorkflowContractBundleWithOverrides(repoRoot, canonicalrouting.ExampleRoot(t, canonicalrouting.FanInBarrier), runtimecontracts.DefaultPlatformSpecFile(repoRoot))
	if err != nil {
		t.Fatalf("load canonical fan-in barrier: %v", err)
	}
	source := semanticview.Wrap(bundle)
	for _, tc := range []struct {
		name  string
		setup func(*testing.T) (fanInBarrierConformanceStore, *sql.DB)
	}{{name: "postgres", setup: func(t *testing.T) (fanInBarrierConformanceStore, *sql.DB) {
		_, db, cleanup := testutil.StartPostgres(t)
		t.Cleanup(cleanup)
		return storetest.AdmitPostgresRuntimeStore(t, db), db
	}}, {name: "sqlite", setup: func(t *testing.T) (fanInBarrierConformanceStore, *sql.DB) {
		backend := storetest.StartSQLiteRuntimeStore(t)
		return backend, storetest.DatabaseForTest(backend)
	}}} {
		t.Run(tc.name, func(t *testing.T) {
			backend, db := tc.setup(t)
			runID := uuid.NewString()
			ctx := runtimecorrelation.WithRunID(testAuthorActivityContextForBundle(context.Background(), conformanceSourceArtifactFact(t, source)), runID)
			seedFanInBarrierRun(t, ctx, backend, db, source, runID)
			runtime := newFanInBarrierRuntime(t, backend, source)
			const periodID = "2026-Q3"
			const portfolioID = "portfolio-one"
			const memberA = "op-a"
			const memberB = "op-b"
			setupID := uuid.NewString()
			publishFanInBarrierEvent(t, ctx, runtime.bus, source, setupID, ".", "portfolio.setup", map[string]any{"portfolio_id": portfolioID, "expected_operating_ids": []string{memberA, memberB}, "period_id": periodID})
			portfolio := loadFanInBarrierPortfolio(t, ctx, runtime.pipeline, periodID)
			setupRoutes, err := backend.ListEventDeliveryRoutes(ctx, setupID)
			if err != nil || len(setupRoutes) != 1 || setupRoutes[0].Target.Route().FlowID != "portfolio" {
				t.Fatalf("root-to-portfolio setup ownership: routes=%#v err=%v", setupRoutes, err)
			}
			parentTarget := setupRoutes[0].Target.Route()
			if portfolio.CurrentState != "awaiting" {
				dumpFanInBarrierEvents(t, ctx, backend, db)
				t.Logf("fan-in runtime diagnostics: %#v", runtime.diagnostics.snapshot())
				t.Fatalf("portfolio state after setup = %q, want awaiting", portfolio.CurrentState)
			}
			activation := loadFanInBarrierActivation(t, ctx, portfolio, periodID)
			retainedJoinRef := activation.JoinRef()
			if activation.Status != joinruntime.StatusOpen || activation.Completed() != 0 || activation.Expected() != 2 {
				t.Fatalf("activation after setup = %#v, want open 0/2", activation)
			}
			publishFanInBarrierEvent(t, ctx, runtime.bus, source, uuid.NewString(), "ingress", "operating.report.requested", map[string]any{"operating_id": memberB, "portfolio_id": portfolioID, "period_id": periodID, "revenue": 22})
			portfolio = loadFanInBarrierPortfolio(t, ctx, runtime.pipeline, periodID)
			activation = loadFanInBarrierActivation(t, ctx, portfolio, periodID)
			if !activation.JoinRef().Equal(retainedJoinRef) {
				t.Fatal("partial arrival changed the retained barrier arm")
			}
			if portfolio.CurrentState != "awaiting" || activation.Status != joinruntime.StatusOpen || activation.Completed() != 1 {
				dumpFanInBarrierEvents(t, ctx, backend, db)
				t.Logf("fan-in runtime diagnostics: %#v", runtime.diagnostics.snapshot())
				t.Fatalf("partial barrier = state:%s activation:%#v, want awaiting open 1/2", portfolio.CurrentState, activation)
			}
			if err := runtime.manager.Shutdown(); err != nil {
				t.Fatalf("retire predecessor fan-in manager: %v", err)
			}
			if err := runtime.schedules.Stop(ctx); err != nil {
				t.Fatalf("retire predecessor join scheduling: %v", err)
			}
			if _, err := runtime.workOwner.RetireAndWait(ctx); err != nil {
				t.Fatalf("join predecessor fan-in work: %v", err)
			}
			if err := runtime.grant.Retire(ctx); err != nil {
				t.Fatalf("retire predecessor fan-in grant: %v", err)
			}
			runtime = newFanInBarrierRuntime(t, backend, source, 2)
			publishFanInBarrierEvent(t, ctx, runtime.bus, source, uuid.NewString(), "ingress", "operating.report.requested", map[string]any{"operating_id": memberA, "portfolio_id": portfolioID, "period_id": periodID, "revenue": 11})
			deadline := time.Now().Add(10 * time.Second)
			for {
				portfolio = loadFanInBarrierPortfolio(t, ctx, runtime.pipeline, periodID)
				activation = loadFanInBarrierActivation(t, ctx, portfolio, periodID)
				if portfolio.CurrentState == "complete" || !time.Now().Before(deadline) {
					break
				}
				time.Sleep(10 * time.Millisecond)
			}
			if !activation.JoinRef().Equal(retainedJoinRef) {
				t.Fatal("restart changed the retained barrier arm")
			}
			requireFanInBarrierReportTargets(t, ctx, backend, db, 2, parentTarget, conformanceNode(t, "portfolio", "portfolio-router").Key())
			requireA2NestedPeriodReadback(t, ctx, backend, db, parentTarget, portfolio)
			if portfolio.CurrentState != "complete" || activation.Status != joinruntime.StatusClosed || activation.CloseReason != joinruntime.CloseReasonComplete {
				t.Fatalf("completed barrier = state:%s activation:%#v", portfolio.CurrentState, activation)
			}
			results, err := activation.Results()
			if err != nil || len(results) != 2 || results[0] != int64(11) || results[1] != int64(22) {
				t.Fatalf("barrier results = %#v err=%v, want declared membership order [11 22]", results, err)
			}
		})
	}
}

