		scheduleEvents = []string{"platform.join_complete", "platform.join_timeout"}
	}
	bus, err := newScopedTestEventBus(t, selected.events, runtimebus.EventBusOptions{ContractBundle: source, SourceArtifactFact: fact, RuntimeInstanceID: runtimeID, WorkOwner: work, PayloadAdmitter: admitter, TestLifecycleProbe: probe, DeliveryAuthority: authority}, scheduleEvents...)
