			workflowPersistence := runtimepipeline.NewWorkflowPersistence(selected)
			if !postgres {
				workflowPersistence = runtimepipeline.NewWorkflowPersistence(selected)
			}
			runID := uuid.NewString()
			entityID := uuid.NewString()
			bundle, sourceFact := workflowTimerStartupRecoverySource(t, "25ms")
			ctx := runtimecorrelation.WithRunID(workflowTimerStartupContext(sourceFact), runID)
			if postgres {
				runlifecyclefixture.RequirePostgres(t, ctx, db, runlifecyclefixture.Fixture{Origin: runlifecyclefixture.ScenarioSetupOrigin(), RunID: runID, Artifact: bundle.SourceArtifact})
			} else {
				runlifecyclefixture.RequireSQLite(t, ctx, db, runlifecyclefixture.Fixture{Origin: runlifecyclefixture.ScenarioSetupOrigin(), RunID: runID, Artifact: bundle.SourceArtifact})
			}
			process := worklifetime.NewProcess()
			source := semanticview.Wrap(bundle)
			rt, err := swarmruntime.NewRuntime(ctx, completeExternalRuntimeTestWorkflowDeps(t, selected, swarmruntime.RuntimeDeps{Config: &config.Config{Runtime: config.RuntimeConfig{RecoveryOnStartup: true}, LLM: config.LLMConfig{Backend: "anthropic"}}, EventStore: selected, EventBusDurable: externalRuntimeTestDurableDependencies(selected), EventPayloadAdmissionBinder: selected, AuthorActivityRegistrars: []swarmruntime.AuthorActivityCatalogRegistrar{selected}, RunLifecycleCandidates: selected, GenericScheduleStore: selected, TimerObligationReader: selected, WorkflowPersistence: workflowPersistence, ManagerStore: selected, ManagerPersistenceRoles: externalRuntimeTestSelectedManagerRoles(selected), DeliveryStore: selected, PipelineObligations: selected.PipelineObligations(), Options: swarmruntime.RuntimeOptions{SelfCheck: false, WorkflowModule: newRuntimeTestWorkflowModule(t, source), LLMRuntime: workflowTimerStartupLLM{}, RuntimeInstanceID: authorActivityTestRuntimeInstanceID, SourceArtifactFact: sourceFact, ProcessWorkOwner: process}}))
			if err != nil {
