		t.Fatalf("decode materialization: %v\n%s", err, materializeOut.String())
	}
	var activateOut bytes.Buffer
	activateCode := runForkRuntimeOwnerHarness(ctx, repo, []string{"--store", "postgres", "--activate", "--run", materialized.ForkRunID, "--allow-source-freeze", "--json"}, &activateOut)
