				?, 'running', ?, ?,
				NULLIF(?, ''), NULLIF(?, ''), NULLIF(?, ''), NULLIF(?, 0),
				NULLIF(?, ''), NULLIF(?, ''), ?
			)
			ON CONFLICT (run_id) DO NOTHING
		`, request.RunID, bundleHash, origin.Kind(), origin.EventID(), origin.EventType(), origin.ServiceID(), origin.Generation(), origin.SourceRunID(), origin.SourceEventID(), request.StartedAt.UTC())
	default:
		return "", fmt.Errorf("semantic run fixture has unsupported dialect %q", m.dialect)
	}
	if err != nil {
		return "", err
	}
	rows, err := result.RowsAffected()
	if err != nil {
		return "", err
	}
	if rows == 1 {
