	}
	tx, err := db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	committed := false
	defer func() {
		if !committed {
			_ = tx.Rollback()
		}
	}()
	if artifact == nil && source.BundleHash() == defaultBundleHash {
		artifact = sourceartifactfixture.Artifact()
	}
	if err := ensureFixtureSourceArtifact(ctx, tx, dialect, source.BundleHash(), artifact); err != nil {
		return err
	}
