func runMutation(ctx context.Context, db *sql.DB, dialect Dialect, fn func(context.Context, *sql.Tx) error) error {
	if db == nil {
		return errors.New("semantic run fixture requires database")
	}
	if fn == nil {
		return errors.New("semantic run fixture mutation requires callback")
	}
	tx, err := db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	committed := false
	defer func() {
		if !committed {
			_ = tx.Rollback()
		}
	}()
	if err := fn(ctx, tx); err != nil {
		return err
	}
	if err := tx.Commit(); err != nil {
		return err
	}
	committed = true
	return nil
}

