				reader sourceArtifactReader
			}{{"missing", missingStageRecoveryReader{sourceArtifactReader: selected, hash: artifacts[2].BundleHash()}}, {"corrupt", corruptStageRecoveryReader{sourceArtifactReader: selected, hash: artifacts[2].BundleHash()}}} {
				t.Run(tc.name, func(t *testing.T) {
