			source := templatereply.LoadSource(t, templatereply.Options{ProviderContinuation: templatereply.ContinuationHuman})
			if findings := runtimebootverify.Run(ctx, source, runtimebootverify.Options{}).HardInvalidities(); len(findings) != 0 {
				t.Fatalf("human-task continuation fixture hard invalidities = %#v", findings)
			}
			backend := backendCase.setup(t)
			cards, ok := backend.(replyHumanTaskConformanceStore)
			if !ok {
				t.Fatalf("%T lacks typed human-task conformance surface", backend)
			}
			runID := uuid.NewString()
			seedDurableReplyConformanceRun(t, ctx, backend, runID, source)
			ctx = runtimecorrelation.WithRunID(testAuthorActivityContextForBundle(ctx, conformanceSourceArtifactFact(t, source)), runID)
			requestBus := newDurableReplyConformanceBus(t, ctx, backend, source)
			requestID := uuid.NewString()
			request := replyConformanceEventForRun(source.ResolveFlowEventReference(templatereply.RequesterFlowID, templatereply.RequestEvent), requestID, runID, templatereply.RequesterFlowID, templatereply.RequesterFlowID+"/account-a", map[string]any{"provider_request_id": requestKey, "account_id": "account-a"})
			if err := requestBus.Publish(ctx, request); err != nil {
				t.Fatalf("publish human-task request: %v", err)
			}
			requestRoutes, err := backend.ListEventDeliveryRoutes(ctx, requestID)
			if err != nil || len(requestRoutes) != 1 || requestRoutes[0].Context.Empty() {
				t.Fatalf("human-task request routes = %#v err=%v", requestRoutes, err)
			}
			deliveryContext := requestRoutes[0].Context
			card := createReplyConformanceHumanTask(t, ctx, cards, runID, requestID, deliveryContext, "main")
			waitReplyConformanceBus(t, ctx, requestBus)
			resumedBus, outcomes := newDurableReplyHumanTaskRuntime(t, ctx, backend, source)
			persistedCard, err := cards.GetDecisionCard(ctx, card.CardID)
			if err != nil {
				t.Fatalf("reload typed human-task card: %v", err)
			}
			persistedContinuation, err := cards.LoadHumanTaskContinuation(ctx, card.CardID)
			if err != nil {
				t.Fatalf("reload typed human-task continuation: %v", err)
			}
			if err := persistedContinuation.Validate(persistedCard); err != nil {
				t.Fatalf("reloaded typed human-task ownership: %v; route=%#v", err, persistedContinuation.RequesterRoute)
			}
			deferredAt := time.Now().UTC().Truncate(time.Microsecond).Add(789 * time.Nanosecond)
			deferred, err := storetest.DecisionCardDomain(cards).ApplyDeferralForTest(ctx, decisioncard.DeferRequest{CardID: card.CardID, PrincipalID: "operator", Until: deferredAt.Add(10 * time.Minute), Now: deferredAt})
			if err != nil {
				t.Fatalf("defer typed human-task card: %v", err)
			}
			deferEvent := replyConformanceCardLifecycleEvent(t, deferred.Card, uuid.NewString(), "mailbox.card_deferred", deferredAt)
			if err := resumedBus.Publish(ctx, deferEvent); err != nil {
				t.Fatalf("publish typed human-task defer: %v", err)
			}
