	startupV2, err := runtimeV2.manager.CanonicalizeDynamicFlowRuntimeStartupReadiness(ctxV2, runtimeV2.sourceArtifactFact, true)
	if err != nil {
		t.Fatalf("canonicalize revised source topology: %v", err)
	}
	if err := runtimeV2.manager.Run(managedConformanceExecutionContextForBundle(t, ctxV2, "dynamic-flow-source-v2", runtimeV2.sourceArtifactFact)); err != nil {
		t.Fatalf("run v2 manager: %v", err)
	}
	if err := runtimeV2.manager.CompleteDynamicFlowRuntimeStartupTopology(ctxV2, startupV2); err != nil {
		t.Fatalf("attach revised source topology: %v", err)
	}
	revisedReadiness := waitNotifyAllChildrenRuntimeReadiness(t, ctxV2, runtimeV2.pipeline, runID, descriptor.FlowInstance)
	v2Agents := loadNotifyAllChildrenAgentsByID(t, ctx, selected)
	if _, found := v2Agents[retiredID]; found {
		t.Fatalf("removed agent %s remains active: %#v", retiredID, v2Agents[retiredID])
	}
	reader := v2Agents[readerID]
	if reader.Config.Role != "reader-v2" || reader.LifecycleGeneration <= readerGenerationV1 {
		t.Fatalf("changed reader = %#v, want reader-v2 generation after %d", reader, readerGenerationV1)
	}
	if writer := v2Agents[writerID]; writer.Config.Role != "writer" || writer.LifecycleGeneration == 0 {
		t.Fatalf("added writer = %#v", writer)
	}
	if _, err := runtimeV2.manager.ResolveAgentConfig(runID, retiredID, descriptor.FlowInstance); err == nil {
		t.Fatalf("removed agent %s remains process-visible", retiredID)
	}
	if cfg, err := runtimeV2.manager.ResolveAgentConfig(runID, readerID, descriptor.FlowInstance); err != nil || cfg.Role != "reader-v2" {
		t.Fatalf("changed reader process config = %#v err=%v", cfg, err)
	}
	if cfg, err := runtimeV2.manager.ResolveAgentConfig(runID, writerID, descriptor.FlowInstance); err != nil || cfg.Role != "writer" {
		t.Fatalf("added writer process config = %#v err=%v", cfg, err)
	}
	if _, exists := reflect.TypeOf(runtimeV2.manager).MethodByName("SpawnAgent"); exists {
		t.Fatal("retired generic agent hire writer remains exported")
	}
	if cfg, err := runtimeV1.manager.ResolveAgentConfig(runID, readerID, descriptor.FlowInstance); err != nil || cfg.Role != "reader-v1" {
		t.Fatalf("stale predecessor process projection changed after replay rejection: %#v err=%v", cfg, err)
	}
	if revisedReadiness.Plan.WorkflowVersion != sourceV2.WorkflowVersion() {
		t.Fatalf("revised runtime readiness = %#v", revisedReadiness)
	}
	if revisedReadiness.CreationEventEmittedAt != initialReadiness.CreationEventEmittedAt {
		t.Fatalf("creation completion changed across source revision: before=%s after=%s", initialReadiness.CreationEventEmittedAt, revisedReadiness.CreationEventEmittedAt)
	}
	terminated, found, err := selected.LoadAgentLifecycleState(ctx, v1Agents[retiredID].Config.Identity)
	if err != nil || !found || terminated.Phase != runtimemanager.AgentLifecycleTerminated {
		t.Fatalf("removed lifecycle state = %#v found=%t err=%v", terminated, found, err)
	}
	retireNotifyAllChildrenRuntimeForReplacement(t, runtimeV2)
	runtimeV3 := newNotifyAllChildrenRuntime(t, selected, sourceV2, time.Now, notifyAllChildrenRuntimeOptions{processTopology: processTopology})
	startupV3, err := runtimeV3.manager.CanonicalizeDynamicFlowRuntimeStartupReadiness(ctxV2, runtimeV3.sourceArtifactFact, true)
	if err != nil {
		t.Fatalf("canonicalize v2 restart topology: %v", err)
	}
	if err := runtimeV3.manager.Run(managedConformanceExecutionContextForBundle(t, ctxV2, "dynamic-flow-source-v2-restart", runtimeV3.sourceArtifactFact)); err != nil {
		t.Fatalf("run v2 restart manager: %v", err)
	}
	if err := runtimeV3.manager.CompleteDynamicFlowRuntimeStartupTopology(ctxV2, startupV3); err != nil {
		t.Fatalf("reconstruct v2 restart topology: %v", err)
	}
	if _, err := runtimeV3.manager.HydrateForStartup(ctxV2); err != nil {
		t.Fatalf("restart hydration: %v", err)
	}
	for _, agentID := range []string{readerID, writerID} {
		if _, err := runtimeV3.manager.ResolveAgentConfig(runID, agentID, descriptor.FlowInstance); err != nil {
			t.Fatalf("restart omitted exact active agent %s", agentID)
		}
	}
	if _, err := runtimeV3.manager.ResolveAgentConfig(runID, retiredID, descriptor.FlowInstance); err == nil {
		t.Fatalf("restart resurrected removed agent %s", retiredID)
	}
	sourceV3 := notifyallchildren.LoadSource(t, notifyallchildren.Options{AgentTopologyRevision: 3, AutoEmitOnCreate: autoEmit})
	retireNotifyAllChildrenRuntimeForReplacement(t, runtimeV3)
	runtimeV4 := newNotifyAllChildrenRuntime(t, selected, sourceV3, time.Now, notifyAllChildrenRuntimeOptions{processTopology: processTopology})
	ctxV3 := runtimecorrelation.WithRunID(testAuthorActivityContextForBundle(context.Background(), runtimeV4.sourceArtifactFact), runID)
	if _, err := selected.ReviseRunSource(ctxV3, runtimerunlifecycle.SourceRevisionRequest{RunID: runID, Source: runtimeV4.sourceArtifactFact}); err != nil {
		t.Fatalf("revise run to v3 source artifact: %v", err)
	}
	startupV4, err := runtimeV4.manager.CanonicalizeDynamicFlowRuntimeStartupReadiness(ctxV3, runtimeV4.sourceArtifactFact, true)
	if err != nil {
		t.Fatalf("canonicalize reintroduced source topology: %v", err)
	}
	if err := runtimeV4.manager.Run(managedConformanceExecutionContextForBundle(t, ctxV3, "dynamic-flow-source-v3", runtimeV4.sourceArtifactFact)); err != nil {
		t.Fatalf("run v3 manager: %v", err)
	}
	if err := runtimeV4.manager.CompleteDynamicFlowRuntimeStartupTopology(ctxV3, startupV4); err != nil {
		t.Fatalf("attach reintroduced source topology: %v", err)
	}
	waitNotifyAllChildrenRuntimeReadiness(t, ctxV3, runtimeV4.pipeline, runID, descriptor.FlowInstance)
	v3Agents := loadNotifyAllChildrenAgentsByID(t, ctx, selected)
	reintroduced := v3Agents[retiredID]
	if reintroduced.Config.Role != "returned" || reintroduced.LifecycleGeneration <= terminated.Generation {
		t.Fatalf("reintroduced lifecycle = %#v, want successor after %#v", reintroduced, terminated)
	}
	if transitions := countNotifyAllChildrenLifecycleTransitions(t, ctx, selected, retiredID, runtimemanager.AgentLifecycleTerminated, runtimemanager.AgentLifecycleRegistered); transitions != 1 {
		t.Fatalf("terminated-to-registered transitions = %d, want exactly one", transitions)
	}
	if reader := v3Agents[readerID]; reader.Config.Role != "reader-v3" {
		t.Fatalf("v3 reader = %#v", reader)
	}
	if cfg, err := runtimeV4.manager.ResolveAgentConfig(runID, retiredID, descriptor.FlowInstance); err != nil || cfg.Role != "returned" {
		t.Fatalf("reintroduced process config = %#v err=%v", cfg, err)
	}
	retireNotifyAllChildrenRuntimeForReplacement(t, runtimeV4)
	runtimeV5 := newNotifyAllChildrenRuntime(t, selected, sourceV3, time.Now, notifyAllChildrenRuntimeOptions{processTopology: processTopology})
	startupV5, err := runtimeV5.manager.CanonicalizeDynamicFlowRuntimeStartupReadiness(ctxV3, runtimeV5.sourceArtifactFact, true)
	if err != nil {
		t.Fatalf("canonicalize v3 restart topology: %v", err)
	}
	if err := runtimeV5.manager.Run(managedConformanceExecutionContextForBundle(t, ctxV3, "dynamic-flow-source-v3-restart", runtimeV5.sourceArtifactFact)); err != nil {
		t.Fatalf("run v3 restart manager: %v", err)
	}
	if err := runtimeV5.manager.CompleteDynamicFlowRuntimeStartupTopology(ctxV3, startupV5); err != nil {
		t.Fatalf("reconstruct v3 restart topology: %v", err)
	}
	if _, err := runtimeV5.manager.HydrateForStartup(ctxV3); err != nil {
		t.Fatalf("reintroduced restart hydration: %v", err)
	}
	for _, agentID := range []string{readerID, writerID, retiredID} {
		if _, err := runtimeV5.manager.ResolveAgentConfig(runID, agentID, descriptor.FlowInstance); err != nil {
			t.Fatalf("reintroduced restart omitted active agent %s", agentID)
		}
	}
	requireSourceRevisionLifecycleDiagnosticReceipts(t, selected, runID)
}

