				second := len(trace.containers) == 2
				trace.mu.Unlock()
				if second && (mode == "cancellation" || mode == "retirement") {
					close(trace.started)
					<-ctx.Done()
					close(trace.cancelled)
					<-trace.finish
					return "", ctx.Err()
				}
