			sourceStatusBefore, err := storetest.ReadRunStatusStorage(ctx, pg, sourceRunID)
			if err != nil {
				t.Fatalf("load source status before activation: %v", err)
			}
			result, err := activateLiveSelectedContractRunFork(ctx, SelectedContractActivationGateRequest{ForkRunID: materialized.ForkRunID, AllowSourceFreeze: true, Store: pg, ExecutionOwner: selectedContractExecutionOwnerForTest(t, pg), SourceLoader: loader})
			failure, ok := runtimefailures.EnvelopeFromError(err)
			if err == nil || !ok || failure.Class != runtimefailures.ClassDependencyUnavailable || failure.Detail.Code != selectedContractDeferredWorkOwnerUnavailable {
				t.Fatalf("ActivateSelectedContractRunFork result=%#v error=%v, failure=%#v", result, err, failure)
			}
			capabilities, ok := failure.Detail.Attributes["capabilities"].([]string)
			if !ok || !slices.Contains(capabilities, test.wantCapability) {
				t.Fatalf("failure capabilities = %#v, want %q", failure.Detail.Attributes["capabilities"], test.wantCapability)
