 commits: 1, state: "closed", status: "running"}, {name: "reviewer_source_events_native_cleanup_shape", source: errors.Join(operationErr), sourceCommitted: true, claims: 1, closes: 1, activations: 1, loads: 1, commits: 1, state: "closed", status: "running"}, {name: "activation_acknowledged_error", activation: operationErr, claims: 1, closes: 1, activations: 1, loads: 1, commits: 1, state: "closed", status: "running"}, {name: "activation_and_close_errors", activation: operationErr, close: settlementErr, claims: 1, closes: 1, activations: 1, loads: 1, commits: 1, state: "closed", status: "running"}, {name: "close_acknowledged_error", close: settlementErr, claims: 1, closes: 1, activations: 1, loads: 1, commits: 1, state: "closed", status: "running"}} {
