				if err != nil {
					t.Fatal(err)
				}
				catalog, err := selected.RegisterAuthorActivityEventCatalog(scope, descriptors)
				if err != nil {
					t.Fatal(err)
				}
				t.Cleanup(catalog.Release)
				sourceID, eventID := uuid.NewString(), uuid.NewString()
				entityID := sourceID
