								if err == nil {
									break
								}
								if err != sql.ErrNoRows {
									t.Fatal(err)
								}
								time.Sleep(20 * time.Millisecond)
							}
							if eventID == "" {
								t.Fatalf("missing generated outcome; calls=%d\n%s", calls.Load(), servedInspectionRunDebugSummary(rt.ReceiverStateReader, seed.RunID))
							}
