			var started struct {
				RunID string `json:"run_id"`
			}
			issue2394ReporterRPC(t, rt, "run.start", map[string]any{"run_id": runID, "bundle_hash": rt.BundleHash, "event_name": "portfolio.opened", "payload": map[string]any{"portfolio_id": portfolio, "threshold": 75}, "idempotency_key": uuid.NewString()}, &started)
			if started.RunID != runID {
				t.Fatalf("HTTP start changed run identity: %+v", started)
			}
