func readServedForkRecipientSourceDomain(t *testing.T, rt servedControlProofRuntime, runID string) map[string][]string {
	t.Helper()
	queries := map[string]string{"events": `SELECT * FROM events WHERE run_id=$1`, "entity_state": `SELECT * FROM entity_state WHERE run_id=$1`, "entity_mutations": `SELECT * FROM entity_mutations WHERE run_id=$1`, "event_deliveries": `SELECT * FROM event_deliveries WHERE run_id=$1`, "event_receipts": `SELECT * FROM event_receipts WHERE event_id IN (SELECT event_id FROM events WHERE run_id=$1)`, "event_delivery_attempts": `SELECT * FROM event_delivery_attempts WHERE delivery_id IN (SELECT delivery_id FROM event_deliveries WHERE run_id=$1)`, "event_delivery_handler_rule_selections": `SELECT * FROM event_delivery_handler_rule_selections WHERE delivery_id IN (SELECT delivery_id FROM event_deliveries WHERE run_id=$1)`}
	out := make(map[string][]string, len(queries))
	for table, query := range queries {
		rows, err := rt.DB.Query(query, runID)
		if err != nil {
			t.Fatalf("read source %s: %v", table, err)
		}
		columns, err := rows.Columns()
		if err != nil {
			t.Fatal(err)
		}
		out[table] = []string{}
		for rows.Next() {
			values := make([]any, len(columns))
			pointers := make([]any, len(columns))
			for i := range values {
				pointers[i] = &values[i]
			}
			if err := rows.Scan(pointers...); err != nil {
				t.Fatal(err)
			}
			for i, value := range values {
				if raw, ok := value.([]byte); ok {
					values[i] = string(raw)
				}
			}
			raw, err := json.Marshal(values)
			if err != nil {
				t.Fatal(err)
			}
			out[table] = append(out[table], string(raw))
		}
		if err := rows.Err(); err != nil {
			t.Fatal(err)
		}
		if err := rows.Close(); err != nil {
			t.Fatal(err)
		}
		sort.Strings(out[table])
	}
	return out
}

