		callback, signing := p.callback, p.signing
		p.mu.Unlock()
		objectChannelIngress(t, callback, signing, "authority-claim", map[string]any{"text": begun.IdentityOperation.Challenge, "principal": "operator-a", "room": "queue-b", "scope": "direct", "message": map[string]any{"id": "authority-claim"}})
