			return result
		}
		time.Sleep(100 * time.Millisecond)
	}
	t.Fatalf("original HTTP reporter did not settle within %s (original objective 5m): unsettled=%d dead=%d diagnosis=%+v", mergeCeiling, unsettled, dead, result)
	return result
}

