			var journalCount int
			if err := db.QueryRow(`SELECT service_id FROM standing_services`).Scan(&serviceID); err != nil {
				t.Fatal(err)
			}
			if err := db.QueryRow(`SELECT COUNT(*) FROM standing_service_journal`).Scan(&journalCount); err != nil {
				t.Fatal(err)
			}
