		if intent.Status != fanoutobligation.StatusClosed || intent.Cursor != intent.Cardinality || intent.Owed != 0 || intent.Runtime.Availability != "available" {
			t.Fatalf("original HTTP list lost settled/live evidence: %+v", intent)
		}
	}
